	/**_# ?? ?? ??? ???? 102104? ?????.*/
	IF EXISTS (
		SELECT * FROM dbo.RestraintReasons WITH (NOLOCK) WHERE RestraintReasonNode.GetAncestor(1) = @hidRestraintReasonNode
	)
	BEGIN
		SET @intReturnValue = 102104;
		GOTO ErrorHandler;
