	/**_# [RestraintReasons] ????? DELETE ???.*/
	DELETE dbo.RestraintReasons WHERE RestraintReasonID = @intRestraintReasonID AND UsedFlag = CAST(0 AS bit);

	/**_# ??? ?? ??? 102103? ?????.*/
