		WHERE POD.PurchaseOrderID = @inbPurchaseOrderID
		ORDER BY SI.PurchaseOrderDetailID;

	IF @@ROWCOUNT = 0
	BEGIN
		SET @intReturnValue = 101145;
		GOTO ErrorHandler;
	END
