ALTER PROCEDURE [dbo].[P_ModReturnRewardFalg]
	  @intAccountID int --// ??? ?? ID	
	, @bitReturnRewardFlag bit --// 0=????? ?? ??, 1=????? ??	
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int
      , @bitCurrentFlag bit;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY
	/**_# [Accounts] ???? UPDATE???.*/
	IF @bitReturnRewardFlag = CAST(1 AS bit) 
	BEGIN
		SELECT @bitCurrentFlag = ReturnRewardFlag 
		FROM dbo.Accounts WITH (NOLOCK) 
		WHERE AccountID = @intAccountID;

		IF @bitCurrentFlag = @bitReturnRewardFlag
		BEGIN
			SET @intReturnValue = 101219;
			GOTO ErrorHandler;
		END

		UPDATE dbo.Accounts 
		   SET ReturnRewardFlag = @bitReturnRewardFlag
		 WHERE AccountID = @intAccountID;
	END
	ELSE
		UPDATE dbo.Accounts 
		   SET ReturnRewardFlag = @bitReturnRewardFlag
		 WHERE AccountID = @intAccountID;

	IF @@ROWCOUNT = 0
	BEGIN
		SET @intReturnValue = 101115;
		GOTO ErrorHandler;
	END
END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	EXEC @intReturnValue = dbo.P_AddErrorLog;

RETURN @intReturnValue;
