SET XACT_ABORT ON;

DECLARE @intReturnValue int
	, @datBasisDate date
	, @nvcTableSuffix nchar(8)
	, @i int
	, @j int
	, @nvcTableName nvarchar(128)
	, @nvcNewTableName nvarchar(128)
