END

BEGIN TRY
	SET @datBasisDate  = DATEADD(DAY, DATEDIFF(DAY, 0, @dtmBasisDate), 0);
	SET @nvcTableSuffix = CONVERT(nchar(8), @datBasisDate, 112);

	INSERT @tblLogTables (TableName)
	SELECT name
	FROM sys.tables
	WHERE name LIKE N'%Logs' AND name NOT IN (N'TableAuditLogs', N'ETLLogs', N'ErrorLogs', N'tmpLogs');

	SELECT @i = 1, @j = @@ROWCOUNT;

	WHILE @i <= @j
	BEGIN
		SELECT @nvcTableName = TableName FROM @tblLogTables WHERE Seq = @i;
		SELECT TOP (1) @nvcDateColumnName = name FROM sys.columns WHERE [object_id] = OBJECT_ID(@nvcTableName, N'U') AND system_type_id IN (40, 42, 43, 58, 61) ORDER BY column_id;

		SET @nvcNewTableName = @nvcTableName + N'_' + @nvcTableSuffix;
		SET @nvcViewName = N'V_' + @nvcTableName;

		SET @nvcStmt = N'
IF OBJECT_ID(N''' + @nvcNewTableName + N''', N''U'') IS NULL
BEGIN
	SELECT * INTO dbo.' + @nvcNewTableName + N' FROM dbo.' + @nvcTableName + N' WHERE 1 = 0;
	ALTER TABLE dbo.' + @nvcNewTableName + N' ADD CONSTRAINT CK_' + @nvcNewTableName + N'_' + @nvcDateColumnName + N' CHECK (' + @nvcDateColumnName + N' >= ''' + CONVERT(nchar(10), @datBasisDate, 121) + N''' AND ' + @nvcDateColumnName + N' < ''' + CONVERT(nchar(10), DATEADD(DAY, 1, @datBasisDate), 121) + N''');
END';

		EXEC (@nvcStmt);

		SET @i += 1;
	END

END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	EXEC @intReturnValue = dbo.P_AddErrorLog;

RETURN @intReturnValue;
GO
