BEGIN TRY
	SET @intColumnCount = 2;

	SET @inbNullBitmap = 
		CASE WHEN @datStartDate IS NOT NULL THEN POWER(2, 0) ELSE 0 END +
		CASE WHEN @datEndDate IS NOT NULL THEN POWER(2, 1) ELSE 0 END;

	/**_# ?? ??? ?????. (FROM, WHERE ?).*/
	SET @nvcStmt = N'
