CREATE PROCEDURE [dbo].[P_GetListAllVisitCharacterLevelJobDistribution]
	  @datBasisDate date --// ?? ??
	, @intWorldID int --// (optional) ?? ID. NULL ??? ?? ?? ?? ??? ?????.
WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
