WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY
	SELECT T.n AS CharacterLevel, ISNULL(SUM(S.UniqueCharacterCount), 0) AS UniqueCharacterCount, ISNULL(SUM(S.UniqueAccountCount), 0) AS UniqueAccountCount, ISNULL(SUM(S.SaleCount), 0) AS SaleCount
		, ISNULL(SUM(S.SaleAmount), 0) AS SaleAmount, ISNULL(SUM(S.SaleAmount) / SUM(S.UniqueCharacterCount), 0) AS AVGSaleAmountPerCharacter, S.NationalityCode
	FROM dbo.Tally T WITH (NOLOCK)
		LEFT OUTER JOIN dbo.ST_DailySalesByCharacter S WITH (NOLOCK) ON CAST(S.CharacterLevel AS int) = T.n
			AND S.BasisDate = @datBasisDate
			AND S.WorldID = COALESCE(@intWorldID, WorldID)
			AND S.JobCode = COALESCE(@inyJobCode, JobCode)
			AND S.PayMethodCode = COALESCE(@inyPayMethodCode, PayMethodCode)
			AND S.PetalIncomeCode = COALESCE(@inyPetalIncomeCode, PetalIncomeCode)
			AND (@inyNationalityCode IS NULL OR S.NationalityCode = @inyNationalityCode)
	WHERE T.n BETWEEN @inyMinCharacterLevel AND @inyMaxCharacterLevel
	GROUP BY T.n, S.NationalityCode
	ORDER BY T.n, S.NationalityCode
END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

