CREATE PROCEDURE [dbo].[P_GetListItemCountMonitoring]
	  @datBasisDateFrom date --// ?? ?? (???)
	, @datBasisDateTo date --// ?? ?? (???)
	, @intWorldID int --// ?? ID
	, @intItemID int = NULL --// ??? ID
	, @inyItemLevel tinyint = NULL --// ??? ??
WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY

    /** ??? ID ? ???? ?? ???? ??? ?? ID ????? ?????. */
    IF @intItemID IS NULL
    BEGIN

        SELECT ICM.BasisDate
             , ICM.WorldID
             , ICM.ItemID
             , DI.ItemName
             , SUM(ICM.ItemRemainCount) AS ItemRemainCount
             , ICM.ItemLevel
             , DC.CharacterName
             , DA.AccountName
             , DC.CharacterID
          FROM dbo.ItemCountMonitoring ICM WITH (NOLOCK)
               LEFT OUTER JOIN dbo.DimItems DI WITH (NOLOCK) ON (ICM.ItemID = DI.ItemID)
               LEFT OUTER JOIN dbo.DimCharacters DC WITH (NOLOCK) ON (ICM.OwnerCharacterID = DC.CharacterID)
               LEFT OUTER JOIN dbo.DimAccounts DA WITH (NOLOCK) ON (DC.AccountID = DA.AccountID)
         WHERE (ICM.BasisDate >= @datBasisDateFrom AND ICM.BasisDate <= @datBasisDateTo)
           AND (ICM.WorldID = @intWorldID)
         GROUP BY ICM.BasisDate, ICM.WorldID, DI.ItemName, ICM.ItemLevel, DC.CharacterName, DA.AccountName, ICM.ItemID, DC.CharacterID;

    END
    /** ??? ID ? ???? ???? ??? ?? ID, ??? ID, ??? ?? ???? ?????. */
    ELSE
    BEGIN

        SELECT ICM.BasisDate
             , ICM.WorldID
             , ICM.ItemID
             , DI.ItemName
             , SUM(ICM.ItemRemainCount) AS ItemRemainCount
             , ICM.ItemLevel
             , DC.CharacterName
             , DA.AccountName
             , DC.CharacterID
          FROM dbo.ItemCountMonitoring ICM WITH (NOLOCK)
               LEFT OUTER JOIN dbo.DimItems DI WITH (NOLOCK) ON (ICM.ItemID = DI.ItemID)
               LEFT OUTER JOIN dbo.DimCharacters DC WITH (NOLOCK) ON (ICM.OwnerCharacterID = DC.CharacterID)
               LEFT OUTER JOIN dbo.DimAccounts DA WITH (NOLOCK) ON (DC.AccountID = DA.AccountID)
         WHERE (ICM.BasisDate >= @datBasisDateFrom AND ICM.BasisDate <= @datBasisDateTo)
           AND (ICM.WorldID = @intWorldID)
           AND (ICM.ItemID = @intItemID)
           AND (@inyItemLevel IS NULL OR ICM.ItemLevel >= @inyItemLevel)
         GROUP BY ICM.BasisDate, ICM.WorldID, DI.ItemName, ICM.ItemLevel, DC.CharacterName, DA.AccountName, ICM.ItemID, DC.CharacterID;

    END

END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	EXEC @intReturnValue = dbo.P_AddErrorLog;

RETURN @intReturnValue;
GO
