	  AND V.ClearFlag = 1
	  AND DC.DeleteFlag = 0
)
SELECT Ranking, CharacterID, CharacterName, ClearTime, WorldName, CharacterClassCode, JobCode, StageStartID 
FROM CTE 
WHERE Ranking <= @intRanking
ORDER BY WorldName, Ranking ;
