    , @inyNationalityCode tinyint = NULL --// 1=Afghanistan, 2=Aland Islands, 3=Albania, 4=Algeria, 5=American Samoa, 6=Andorra, 7=Angola, 8=Anguilla, 9=Antarctica, 10=Antigua and Barbuda, 11=Argentina, 12=Armenia, 13=Aruba, 14=Australia, 15=Austria, 16=Azerbaijan, 17=Bahamas, 18=Bahrain, 19=Bangladesh, 20=Barbados, 21=Belarus, 22=Belgium, 23=Belize, 24=Benin, 25=Bermuda, 26=Bhutan, 27=Bolivia, 28=Bosnia and Herzegovina, 29=Botswana, 30=Bouvet Island, 31=Brazil, 32=British Indian Ocean Territory, 33=Brunei Darussalam, 34=Bulgaria, 35=Burkina Faso, 36=Burundi, 37=Cambodia, 38=Cameroon, 39=Canada, 40=Cape Verde, 41=Cayman Islands, 42=Central African Republic, 43=Chad, 44=Chile, 45=China, 46=Colombia, 47=Comoros, 48=Congo, 49=Congo The Democratic Republic of the, 50=Cook Islands, 51=Costa Rica, 52=Cote D'Ivoire, 53=Croatia, 54=Cuba, 55=Cyprus, 56=Czech Republic, 57=Denmark, 58=Djibouti, 59=Dominica, 60=Dominican Republic, 61=Ecuador, 62=Egypt, 63=El Salvador, 64=Equatorial Guinea, 65=Eritrea, 66=Estonia, 67=Ethiopia, 68=Europe, 69=Falkland Islands (Malvinas), 70=Faroe Islands, 71=Fiji, 72=Finland, 73=France, 74=French Guiana, 75=French Polynesia, 76=Gabon, 77=Gambia, 78=Georgia, 79=Germany, 80=Ghana, 81=Gibraltar, 82=Greece, 83=Greenland, 84=Grenada, 85=Guadeloupe, 86=Guam, 87=Guatemala, 88=Guernsey, 89=Guinea, 90=Guinea-Bissau, 91=Guyana, 92=Haiti, 93=Holy See (Vatican City State), 94=Honduras, 95=Hong Kong, 96=Hungary, 97=Iceland, 98=India, 99=Indonesia, 100=Iran Islamic Republic of, 101=Iraq, 102=Ireland, 103=Isle of Man, 104=Israel, 105=Italy, 106=Jamaica, 107=Japan, 108=Jersey, 109=Jordan, 110=Kazakstan, 111=Kenya, 112=Kiribati, 113=Korea Democratic People's Republic of, 114=????, 115=Kuwait, 116=Kyrgyzstan, 117=Lao People's Democratic Republic, 118=Latvia, 119=Lebanon, 120=Lesotho, 121=Liberia, 122=Libyan Arab Jamahiriya, 123=Liechtenstein, 124=Lithuania, 125=Luxembourg, 126=Macau, 127=Macedonia, 128=Madagascar, 129=Malawi, 130=Malaysia, 131=Maldives, 132=Mali, 133=Malta, 134=Marshall Islands, 135=Martinique, 136=Mauritania, 137=Mauritius, 138=Mayotte, 139=Mexico, 140=Micronesia Federated States of, 141=Moldova Republic of, 142=Monaco, 143=Mongolia, 144=Montenegro, 145=Montserrat, 146=Morocco, 147=Mozambique, 148=Myanmar, 149=Namibia, 150=Nauru, 151=Nepal, 152=Netherlands, 153=Netherlands Antilles, 154=New Caledonia, 155=New Zealand, 156=Nicaragua, 157=Niger, 158=Nigeria, 159=Niue, 160=Norfolk Island, 161=Northern Mariana Islands, 162=Norway, 163=Oman, 164=Pakistan, 165=Palau, 166=Palestinian Territory Occupied, 167=Panama, 168=Papua New Guinea, 169=Paraguay, 170=Peru, 171=Philippines, 172=Poland, 173=Portugal, 174=Puerto Rico, 175=Qatar, 176=Reunion, 177=Romania, 178=Russian Federation, 179=Rwanda, 180=Saint Kitts and Nevis, 181=Saint Lucia, 182=Saint Pierre and Miquelon, 183=Saint Vincent and the Grenadines, 184=Samoa, 185=San Marino, 186=Sao Tome and Principe, 187=Satellite Provider, 188=Saudi Arabia, 189=Senegal, 190=Serbia, 191=Seychelles, 192=Sierra Leone, 193=Singapore, 194=Slovakia, 195=Slovenia, 196=Solomon Islands, 197=Somalia, 198=South Africa, 199=Spain, 200=Sri Lanka, 201=Sudan, 202=Suriname, 203=Swaziland, 204=Sweden, 205=Switzerland, 206=Syrian Arab Republic, 207=Taiwan, 208=Tajikistan, 209=Tanzania United Republic of, 210=Thailand, 211=Togo, 212=Tokelau, 213=Tonga, 214=Trinidad and Tobago, 215=Tunisia, 216=Turkey, 217=Turkmenistan, 218=Turks and Caicos Islands, 219=Tuvalu, 220=Uganda, 221=Ukraine, 222=United Arab Emirates, 223=United Kingdom, 224=United States, 225=United States Minor Outlying Islands, 226=Uruguay, 227=Uzbekistan, 228=Vanuatu, 229=Venezuela, 230=Vietnam, 231=Virgin Islands British, 232=Virgin Islands U.S., 233=Wallis and Futuna, 234=Yemen, 235=Zambia, 236=Zimbabwe
WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

SET @datStartDate = DATEADD(DAY, - DATEPART(WEEKDAY, @datStartDate) + 1, @datStartDate);
SET @datEndDate = DATEADD(DAY, - DATEPART(WEEKDAY, @datEndDate) + 1, @datEndDate);

BEGIN TRY
	;WITH C1 AS (
		SELECT DATEADD(DAY, - DATEPART(WEEKDAY, BasisDate) + 1, BasisDate) AS  BasisDate, SUM(RUCount) AS RUCount
		FROM dbo.ST_DailyDashboard WITH (NOLOCK)
		WHERE BasisDate BETWEEN @datStartDate AND DATEADD(DAY, 6, @datEndDate) AND (@inyNationalityCode IS NULL OR NationalityCode = @inyNationalityCode)
		GROUP BY DATEADD(DAY, - DATEPART(WEEKDAY, BasisDate) + 1, BasisDate)
	), C2 AS (
		SELECT AccountRegisterDate
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 1 THEN WR.RevisitCount END), 0) AS VisitCount2
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 1 THEN WR.RevisitRatio END), 0) AS VisitRatio2
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 2 THEN WR.RevisitCount END), 0) AS VisitCount3
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 2 THEN WR.RevisitRatio END), 0) AS VisitRatio3
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 3 THEN WR.RevisitCount END), 0) AS VisitCount4
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 3 THEN WR.RevisitRatio END), 0) AS VisitRatio4
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 4 THEN WR.RevisitCount END), 0) AS VisitCount5
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 4 THEN WR.RevisitRatio END), 0) AS VisitRatio5
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 5 THEN WR.RevisitCount END), 0) AS VisitCount6
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 5 THEN WR.RevisitRatio END), 0) AS VisitRatio6
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 6 THEN WR.RevisitCount END), 0) AS VisitCount7
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 6 THEN WR.RevisitRatio END), 0) AS VisitRatio7
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 7 THEN WR.RevisitCount END), 0) AS VisitCount8
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 7 THEN WR.RevisitRatio END), 0) AS VisitRatio8
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 8 THEN WR.RevisitCount END), 0) AS VisitCount9
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 8 THEN WR.RevisitRatio END), 0) AS VisitRatio9
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 9 THEN WR.RevisitCount END), 0) AS VisitCount10
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 9 THEN WR.RevisitRatio END), 0) AS VisitRatio10
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 10 THEN WR.RevisitCount END), 0) AS VisitCount11
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 10 THEN WR.RevisitRatio END), 0) AS VisitRatio11
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 11 THEN WR.RevisitCount END), 0) AS VisitCount12
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 11 THEN WR.RevisitRatio END), 0) AS VisitRatio12
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 12 THEN WR.RevisitCount END), 0) AS VisitCount13
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 12 THEN WR.RevisitRatio END), 0) AS VisitRatio13
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 13 THEN WR.RevisitCount END), 0) AS VisitCount14
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 13 THEN WR.RevisitRatio END), 0) AS VisitRatio14
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 14 THEN WR.RevisitCount END), 0) AS VisitCount15
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 14 THEN WR.RevisitRatio END), 0) AS VisitRatio15
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 15 THEN WR.RevisitCount END), 0) AS VisitCount16
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 15 THEN WR.RevisitRatio END), 0) AS VisitRatio16
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 16 THEN WR.RevisitCount END), 0) AS VisitCount17
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 16 THEN WR.RevisitRatio END), 0) AS VisitRatio17
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 17 THEN WR.RevisitCount END), 0) AS VisitCount18
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 17 THEN WR.RevisitRatio END), 0) AS VisitRatio18
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 18 THEN WR.RevisitCount END), 0) AS VisitCount19
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 18 THEN WR.RevisitRatio END), 0) AS VisitRatio19
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 19 THEN WR.RevisitCount END), 0) AS VisitCount20
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 19 THEN WR.RevisitRatio END), 0) AS VisitRatio20
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 20 THEN WR.RevisitCount END), 0) AS VisitCount21
			, ISNULL(MAX(CASE DATEDIFF(WEEK, WR.AccountRegisterDate, WR.BasisDate) WHEN 20 THEN WR.RevisitRatio END), 0) AS VisitRatio21
		FROM dbo.ST_WeeklyRevisit WR WITH (NOLOCK)
		WHERE WR.AccountRegisterDate BETWEEN @datStartDate AND @datEndDate AND (@inyNationalityCode IS NULL OR NationalityCode = @inyNationalityCode)
		GROUP BY WR.AccountRegisterDate
	)
	SELECT CONVERT(varchar(10), C2.AccountRegisterDate, 121) + ' ~ ' + CONVERT(varchar(10), DATEADD(DAY, 6, C2.AccountRegisterDate), 121) AS Period
		, C1.RUCount, C2.VisitCount2, VisitRatio2, VisitCount3, VisitRatio3, VisitCount4, VisitRatio4, VisitCount5, VisitRatio5, VisitCount6, VisitRatio6, VisitCount7, VisitRatio7
		, VisitCount8, VisitRatio8, VisitCount9, VisitRatio9, VisitCount10, VisitRatio10, VisitCount11, VisitRatio11, VisitCount12, VisitRatio12, VisitCount13, VisitRatio13
		, VisitCount14, VisitRatio14, VisitCount15, VisitRatio15, VisitCount16, VisitRatio16, VisitCount17, VisitRatio17, VisitCount18, VisitRatio18, VisitCount19, VisitRatio19
		, VisitCount20, VisitRatio20, VisitCount21, VisitRatio21
	FROM C1
		INNER JOIN C2 ON C2.AccountRegisterDate = C1.BasisDate
	ORDER BY C2.AccountRegisterDate;
END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	EXEC @intReturnValue = dbo.P_AddErrorLog;

RETURN @intReturnValue;
GO
