	, @vchStartLoginIP varchar(15) = NULL --// ?? ?? IP ??
	, @vchEndLoginIP varchar(15) = NULL --// ?? ? IP ??
	, @dt2StartLoginDate datetime2(0) --// (?? ??) ?? ?? ?? - ??? ?? ??
	, @dt2EndLoginDate datetime2(0) --// (?? ??) ?? ? ?? - ??? ?? ??
