BEGIN TRY
	SELECT A.BasisDate, A.ServerName, A.DatabaseName, A.TableName, A.IndexName
		, (B.UserScans - A.UserScans) AS UserScans
		, (B.UserSeeks - A.UserSeeks) AS UserSeeks	
