		VALUES (@dt2LogDate, @inbCharacterID, @inyCoinTypeCode, @inyCoinChangeCode, @inbCurrentCoin, @inbChangedCoin, @intChannelID, @intMapID, @inbCoinChangeFKey, dbo.FN_IP2IPNumber(@vchIP));

