BEGIN TRY
	IF EXISTS(SELECT * FROM dbo.DWCChannels WHERE DWCEndTime >= @dt2Now AND EnableFlag = 1)
	BEGIN
		SET @intReturnValue = 103363;
		GOTO ErrorHandler;
	END

	IF EXISTS (SELECT * FROM dbo.DWCChannels WHERE EnableFlag = 0 AND DataInitFlag = 0)
	BEGIN
