	VALUES (@inbCharacterID, @intCharacterLevel, @intCharacterExp, 0, COALESCE(@inyJobCode2, @inyJobCode1, @inyCharacterClassCode), @intHairColor, @intEyeColor, @intSkinColor, @intLastMapID, 0, 0, @intPositionX, @intPositionY, @intPositionZ, @fltRotate, @intCoin, 0, CAST(DATEADD(HOUR, 4, DATEADD(DAY, DATEDIFF(DAY, 0, @dtmNow) + CASE WHEN DATEPART(HOUR, @dtmNow) BETWEEN 0 AND 3 THEN 0 ELSE 1 END, 0)) AS smalldatetime), @inyRebirthCoin, @inyPCRoomRebirthCoin, @intSkillPoint, '1900-01-01', 0, 0, 0, 0, 0, 0, 0, 65535);

