	/**_# DWC ? ??? ?????. */
	INSERT dbo.DWCTeamHistory (DWCTeamID, DWCTeamHistoryCode, CharacterID, RegisterDate)
	VALUES (@intDWCTeamID, 2, @inbCharacterID, @dt2Now)	

END TRY
