BEGIN TRY
	IF (SELECT SUM(FieldCount) FROM dbo.VIX_FieldCountByCharacter WITH (NOLOCK, NOEXPAND) WHERE CharacterID = @inbCharacterID) >= @intMaxFieldCount
	BEGIN
		SET @intReturnValue = 103284;
