	  , @intRequestedCount int
	  , @bitBlockedByFriend bit = CAST(0 AS bit)
	  , @bitFriendRequestFlag bit;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY
	/**_# ?? ?? ?????.*/
	SELECT @intFriendCount = FriendCount FROM dbo.VIX_FriendTotals WITH (NOEXPAND, NOLOCK) WHERE CharacterID = @inbCharacterID;

	/**_## ?? ?? ???? ???? 103129? ?????.*/
	IF @intFriendCount >= @intFriendCountLimit
	BEGIN
		SET @intReturnValue = 103129;
		GOTO ErrorHandler;
	END
	
