	SELECT @inbFriendCharacterID = CharacterID, @intFriendAccountID = AccountID, @inyAccountLevelCode = AccountLevelCode, @bitMobileAuthenticationFlag = MobileAuthenticationFlag
	FROM dbo.Characters WITH (NOLOCK)
	WHERE CharacterName = @nvcFriendCharacterName AND DeleteFlag = CAST(0 AS bit);

	/**_# ??? ??? ???? ???? ??? 103131? ?????.*/
	IF @@ROWCOUNT = 0
	BEGIN
		SET @intReturnValue =103131;
		GOTO ErrorHandler;
	END

	IF @inyFriendStatusCode = 3
	BEGIN
