	UPDATE dbo.Friends 
	SET FriendStatusCode = 1
	WHERE FriendCharacterID = @inbCharacterID AND CharacterID = @inbFriendCharacterID AND FriendStatusCode = 3;
	
	IF @@ROWCOUNT > 0
	BEGIN		
		SET @inyFriendStatusCode = 1;
	END	

	/**_# [Friends] ???? INSERT???.*/
	/**_## ?? ??? ???? ?? ????? 103134? ?????.*/
	/**_## ???? ???? ??? 103102? ?????.*/
	INSERT dbo.Friends (CharacterID, FriendCharacterID, FriendMemo, FriendGroupID, RegisterDate, FriendStatusCode)
	VALUES (@inbCharacterID, @inbFriendCharacterID, @nvcFriendMemo, @intFriendGroupID, GETDATE(), ISNULL(@inyFriendStatusCode, 0));
END TRY
BEGIN CATCH
	IF ERROR_NUMBER() = 547 AND ERROR_MESSAGE() LIKE N'%FK_Characters_Friends_CharacterID%'
		SET @intReturnValue = 103102;

	ELSE IF ERROR_NUMBER() = 2627 AND ERROR_MESSAGE() LIKE N'%PK_Friends%'
