	, @intMaxGuildMemberCount int = NULL--// ?? ??? ?
	, @dt2RegisterDate datetime2(0) OUTPUT --// ?? ?? ??
	, @bitDeleteGuildRecrutment bit = NULL OUTPUT --//0=??????, 1=??????
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int;

DECLARE @intCurrentGuildMemberCount int	--//?? ??? ?

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY
	SET @dt2RegisterDate = GETDATE();
	SET @bitDeleteGuildRecrutment = 0;

	-- ?? ?? ?? ?? ???? ???? ?? ?????? DB?? ?? ?? ?? ?? ???? ???? ???? ???? ??? ???.(?? ?? ????? ???? ?? ???? ??)
	IF @intMaxGuildMemberCount IS NULL
		SELECT @intMaxGuildMemberCount = GuildMaxMemberCount 
		FROM dbo.Guilds WITH (NOLOCK, INDEX(PK_Guilds), FORCESEEK) 
		WHERE GuildID = @intGuildID;

	BEGIN TRANSACTION;

	/**_# [GuildMembers] ???? INSERT???.*/
	INSERT dbo.GuildMembers (GuildID, CharacterID, GuildMemberRoleCode, SelfIntroduction, RegisterDate, CharacterJoinLevel)
	SELECT GuildID, @inbCharacterID, 4, @nvcDefaultSelfIntroduction, @dt2RegisterDate, @inyCharacterLevel
	FROM dbo.Guilds WITH (UPDLOCK)
	WHERE GuildID = @intGuildID AND CloseFlag = CAST(0 AS bit);

