	COMMIT TRANSACTION;

	/**_## ?? ?? ? ?? ?? ??? DELETE ???.*/
	DELETE dbo.GuildJoinCharacters 
	FROM dbo.GuildJoinCharacters WITH (INDEX(IX_NN_GuildJoinCharacters_CharacterID), FORCESEEK)
	WHERE CharacterID = @inbCharacterID
	OPTION (KEEPFIXED PLAN);

