	  @dt2BasisDate datetime2(0)
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY
	/**_# [PeriodicReset] ???? INSERT???.*/
	INSERT dbo.PotentialBoxStat (BasisDate, PotentialBoxValue, UserCount)
	SELECT DATEADD(MINUTE, DATEDIFF(MINUTE, 0, @dt2BasisDate), 0), PeriodicResetValue, Cnt
	FROM dbo.VIX_PotentialBoxStat WITH(NOEXPAND, NOLOCK)
END TRY
BEGIN CATCH

	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	EXEC @intReturnValue = dbo.P_AddErrorLog @intPROCID = @@PROCID;

RETURN @intReturnValue;
GO
