		VALUES (@inbStageStartID, @inbCharacterID, @inyJobCode, @inyCharacterLevel, @bitClearFlag, @inyClearGradeCode, @intMaxComboCount, @inyBossKillCount, @intRewardCharacterExp, @intBonusCharacterExp, @intClearPoint, @intBonusClearPoint, @intClearTime, @inyClearRound, @bitTeacherPupilFlag, @insNestFatigue);

