	/**_# ?? ??? ???? ?? ????? ?????.*/

	UPDATE dbo.GuildWarSchedule
	   SET FinalProgressFlag = 0
	 WHERE GuildWarScheduleID = @insGuildWarScheduleID;

	COMMIT TRAN;
	
