	/**_# ? ?? ???? ??? ?? ???? UPDATE ???.*/
	UPDATE dbo.GuildMembers
	SET GuildMemberRoleCode = 0
	WHERE GuildID = @intGuildID AND CharacterID = @inbNewGuildMasterCharacterID AND GuildMemberRoleCode > 0;

	/**_## UPDATE? ???? ??? 103245? ?????.*/
	IF @@ROWCOUNT = 0
	BEGIN
