		WHERE ItemID > 0 ' +				
				CASE WHEN @vchItemCategoryIDs > '' THEN N' AND ItemCategoryID IN (' + @vchItemCategoryIDs + N')' ELSE N'' END +
				CASE WHEN @nvcItemName > N'' THEN N' AND ItemName LIKE @nvcItemName' ELSE N'' END +N'
