	SELECT @intTotalCount = COUNT(*)
	FROM A
	OPTION (MAXDOP 1, KEEP PLAN, KEEPFIXED PLAN)';

	/**_# ?? ??? ?????.*/
	EXEC dbo.sp_executesql @nvcStmt
