          AND DeleteFlag = 0
	END

	UPDATE dbo.PVPScores
	SET PVPExp = 0, PVPLevel = 1
	WHERE CharacterID = @inbCharacterID;
	
	IF @@ROWCOUNT = 0
	BEGIN
		SET @intReturnValue = 103388;
