	, @inyCharacterClassCode tinyint = NULL --// ??? ??? ??
	, @inyCharacterAbilityCode tinyint = NULL --// ??? ?? ??	
	, @intRanking int = NULL OUTPUT --// ??
--WITH EXECUTE AS 'SPExecutor'
