	version 1 : ItemID/int, TradeCount/int, RegistedCount/int, MaxPrice/int, ItemName/nvarchar(50), ItemRankCode/tinyint
	version 2 : version1 + ItemLevel/tinyint, ItemCategoryID/tinyint, RepresentativeItemSerial/bigint
