			LEFT OUTER JOIN MissionAssignDates MD ON 1 = 1
		WHERE CHI.CharacterID = @inbCharacterID
		OPTION (FORCE ORDER, LOOP JOIN, MAXDOP 1, KEEPFIXED PLAN);

