CREATE PROCEDURE [dbo].[P_GetCharacterPVPRanking]
	  @inbCharacterID bigint = NULL --// ???ID	
	, @nvcCharacterName nvarchar(30) = NULL --// ???ID	
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY
	/**_# [PVPRanking] ???? SELECT???.*/
	IF @inbCharacterID IS NOT NULL
		SELECT PR.CharacterName, PR.JobCode, PR.GuildName, PR.PVPExp, PR.[Kill], PR.Death, PR.PVPClassRank, PR.PVPClassRatio, PR.TotalRank, PR.CharacterClassRank, PR.CharacterSubClassRank, 
			CASE WHEN PR.ChangedTotalRank IS NULL THEN 2 
				 WHEN PR.ChangedTotalRank > 0 THEN 1 
				 WHEN PR.ChangedTotalRank < 0 THEN -1 
				 ELSE 0 END AS ChangedTotalRank,
			CASE WHEN PR.ChangedCharacterClassRank IS NULL THEN 2 
				 WHEN PR.ChangedCharacterClassRank > 0 THEN 1 
				 WHEN PR.ChangedCharacterClassRank < 0 THEN -1 
				 ELSE 0 END AS ChangedCharacterClassRank,
 			CASE WHEN PR.ChangedCharacterSubClassRank IS NULL THEN 2 
				 WHEN PR.ChangedCharacterSubClassRank > 0 THEN 1 
				 WHEN PR.ChangedCharacterSubClassRank < 0 THEN -1 
				 ELSE 0 END AS ChangedCharacterSubClassRank,
			CH.CharacterLevel, PS.PVPLevel
		FROM dbo.PVPRanking PR WITH (NOLOCK) INNER JOIN dbo.CharacterStatus CH WITH (NOLOCK) ON PR.CharacterID = CH.CharacterID
	         INNER JOIN dbo.PVPScores PS WITH (NOLOCK) ON PR.CharacterID = PS.CharacterID 
		WHERE PR.CharacterID = @inbCharacterID;
	ELSE IF @nvcCharacterName IS NOT NULL
		SELECT PR.CharacterName, PR.JobCode, PR.GuildName, PR.PVPExp, PR.[Kill], PR.Death, PR.PVPClassRank, PR.PVPClassRatio, PR.TotalRank, PR.CharacterClassRank, PR.CharacterSubClassRank, 
			CASE WHEN PR.ChangedTotalRank IS NULL THEN 2 
				 WHEN PR.ChangedTotalRank > 0 THEN 1 
				 WHEN PR.ChangedTotalRank < 0 THEN -1 
				 ELSE 0 END AS ChangedTotalRank,
			CASE WHEN PR.ChangedCharacterClassRank IS NULL THEN 2 
				 WHEN PR.ChangedCharacterClassRank > 0 THEN 1 
				 WHEN PR.ChangedCharacterClassRank < 0 THEN -1 
				 ELSE 0 END AS ChangedCharacterClassRank,
 			CASE WHEN PR.ChangedCharacterSubClassRank IS NULL THEN 2 
				 WHEN PR.ChangedCharacterSubClassRank > 0 THEN 1 
				 WHEN PR.ChangedCharacterSubClassRank < 0 THEN -1 
				 ELSE 0 END AS ChangedCharacterSubClassRank,
			CH.CharacterLevel, PS.PVPLevel
		FROM dbo.PVPRanking PR WITH (NOLOCK) INNER JOIN dbo.CharacterStatus CH WITH (NOLOCK) ON PR.CharacterID = CH.CharacterID
			 INNER JOIN dbo.PVPScores PS WITH (NOLOCK) ON PR.CharacterID = PS.CharacterID 
		WHERE PR.CharacterName = @nvcCharacterName;
	ELSE
		SELECT PR.CharacterName, PR.JobCode, PR.GuildName, PR.PVPExp, PR.[Kill], PR.Death, PR.PVPClassRank, PR.PVPClassRatio, PR.TotalRank, PR.CharacterClassRank, PR.CharacterSubClassRank, 
			CASE WHEN PR.ChangedTotalRank IS NULL THEN 2 
				 WHEN PR.ChangedTotalRank > 0 THEN 1 
				 WHEN PR.ChangedTotalRank < 0 THEN -1 
				 ELSE 0 END AS ChangedTotalRank,
			CASE WHEN PR.ChangedCharacterClassRank IS NULL THEN 2 
				 WHEN PR.ChangedCharacterClassRank > 0 THEN 1 
				 WHEN PR.ChangedCharacterClassRank < 0 THEN -1 
				 ELSE 0 END AS ChangedCharacterClassRank,
 			CASE WHEN PR.ChangedCharacterSubClassRank IS NULL THEN 2 
				 WHEN PR.ChangedCharacterSubClassRank > 0 THEN 1 
				 WHEN PR.ChangedCharacterSubClassRank < 0 THEN -1 
				 ELSE 0 END AS ChangedCharacterSubClassRank,
			CH.CharacterLevel, PS.PVPLevel
		FROM dbo.PVPRanking PR WITH (NOLOCK) INNER JOIN dbo.CharacterStatus CH WITH (NOLOCK) ON PR.CharacterID = CH.CharacterID
			 INNER JOIN dbo.PVPScores PS WITH (NOLOCK) ON PR.CharacterID = PS.CharacterID 
		WHERE PR.CharacterID = @inbCharacterID AND PR.CharacterName = @nvcCharacterName;	
END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	EXEC @intReturnValue = dbo.P_AddErrorLog;

RETURN @intReturnValue;
GO
