CREATE PROCEDURE [dbo].[P_GetGlobalEventEntryCount]
	  @inbCharacterID bigint = NULL --// ???ID
	, @intGlobalEventScheduleID int --// ????????ID
	, @intEntryCount int = NULL OUTPUT --// ????
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY

	-- ?? ??? ?? ???? ??
	IF @inbCharacterID IS NOT NULL
	BEGIN
		SELECT @intEntryCount = EntryCount
		  FROM dbo.GlobalEventEntryCount WITH (NOLOCK)
		 WHERE (CharacterID = @inbCharacterID)
		   AND (GlobalEventScheduleID = @intGlobalEventScheduleID);
	END
	-- ?? ???? ??
	ELSE
	BEGIN
		SELECT @intEntryCount = EntryCountSum
		  FROM dbo.VIX_GlobalEventEntryCount WITH (NOLOCK, NOEXPAND)
		 WHERE (GlobalEventScheduleID = @intGlobalEventScheduleID);
	END

END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	EXEC @intReturnValue = dbo.P_AddErrorLog;

RETURN @intReturnValue;
GO
