CREATE PROCEDURE [dbo].[P_GetGuildRecruitment]
	  @intGuildID int --// ?? ID
	, @intVersion int = 5 --// SP ??
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
