BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY
	SET @intLogTableSuffix = dbo.FN_LogTableSuffix(@dt2LogDate);

	IF @intLogTableSuffix = 0
		SELECT LogDate, CharacterID, CoinCountBefore, CoinCountAfter, MapID, IP
		FROM dbo.CashRebirthCoinLogs0
		WHERE LogDate >= @dt2LogDate AND LogDate < DATEADD(DAY, 1, @dt2LogDate)
		OPTION (MAXDOP 1);

	ELSE IF @intLogTableSuffix = 1
		SELECT LogDate, CharacterID, CoinCountBefore, CoinCountAfter, MapID, IP
		FROM dbo.CashRebirthCoinLogs1
		WHERE LogDate >= @dt2LogDate AND LogDate < DATEADD(DAY, 1, @dt2LogDate)
		OPTION (MAXDOP 1);

	ELSE
		SELECT LogDate, CharacterID, CoinCountBefore, CoinCountAfter, MapID, IP
		FROM dbo.CashRebirthCoinLogs2
		WHERE LogDate >= @dt2LogDate AND LogDate < DATEADD(DAY, 1, @dt2LogDate)
		OPTION (MAXDOP 1);

END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

