DECLARE @intReturnValue int;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY

	/**_# ??? ?? ??? ??? ?? ?? 1?? ?????. */
    SELECT PT.BasisDate
         , PT.OpeningPointSum
         , C.CharacterID
         , C.CharacterName
         , G.GuildID
         , G.GuildName
		 , ROW_NUMBER() OVER(PARTITION BY PT.BasisDate ORDER BY C.CharacterName) AS SortNumber
	  INTO #Temp_Result
      FROM dbo.GuildWarOpeningPointDailyTotal PT WITH (NOLOCK)
           INNER JOIN dbo.Characters C WITH (NOLOCK) ON (PT.CharacterID = C.CharacterID)
           INNER JOIN dbo.Guilds G WITH (NOLOCK) ON (PT.GuildID = G.GuildID)
     WHERE PT.Ranking = 1
     ORDER BY PT.BasisDate;

	/**_## ?? 1?? ???? ???? ?????? ???? ?? ?? ???? 1?? ?????. */
	SELECT BasisDate
         , OpeningPointSum
         , CharacterID
         , CharacterName
         , GuildID
         , GuildName
	  FROM #Temp_Result
	 WHERE SortNumber = 1;

	DROP TABLE #Temp_Result;

END TRY
