               INNER JOIN dbo.Guilds G WITH (NOLOCK) ON (GWPV.GuildID = G.GuildID)
         GROUP BY G.GuildID, G.GuildName
         ORDER BY COUNT(GWPV.CharacterID) DESC
    END

