CREATE PROCEDURE [dbo].[P_GetListMapStayLog]
	  @dtmBasisDate datetime --// ?? ??
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int, @dt2BasisDate datetime2(0) = CAST(CAST(@dtmBasisDate AS date) AS datetime2(0)), @intLogTableSuffix int;;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY
	SET @intLogTableSuffix = dbo.FN_LogTableSuffix(@dt2BasisDate);

	IF @intLogTableSuffix = 0
		SELECT ExitDate, MapID, CharacterID, JobCode, CharacterLevel, EntranceDate
		FROM dbo.MapStayLogs0 WITH(NOLOCK)
		WHERE ExitDate >= @dt2BasisDate AND ExitDate < DATEADD(DAY, 1, @dt2BasisDate)
		OPTION (MAXDOP 1);

	ELSE IF @intLogTableSuffix = 1
		SELECT ExitDate, MapID, CharacterID, JobCode, CharacterLevel, EntranceDate
		FROM dbo.MapStayLogs1 WITH(NOLOCK)
		WHERE ExitDate >= @dt2BasisDate AND ExitDate < DATEADD(DAY, 1, @dt2BasisDate)
		OPTION (MAXDOP 1);

	ELSE
		SELECT ExitDate, MapID, CharacterID, JobCode, CharacterLevel, EntranceDate
		FROM dbo.MapStayLogs2 WITH(NOLOCK)
		WHERE ExitDate >= @dt2BasisDate AND ExitDate < DATEADD(DAY, 1, @dt2BasisDate)
		OPTION (MAXDOP 1);

END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

