	ELSE IF @intVersion = 2
	BEGIN
		EXEC @intReturnValue = dbo.P_GetListMaterializedItemSubV2
			  @inbCharacterID = @inbCharacterID
			, @inyItemLocationCode = @inyItemLocationCode
