CREATE PROCEDURE [dbo].[P_GetListMaterializedItemSubV2]
	  @inbCharacterID bigint --// ??? ID
	, @inyItemLocationCode tinyint --// ItemLocationCode
	, @intAccountID int --// ?? ID
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY
	/**_# ??? ??? ??? ?????.*/
	IF @inyItemLocationCode IS NOT NULL
	BEGIN
		IF @inyItemLocationCode BETWEEN 17 AND 18
			SELECT MI.ItemLocationCode, MI.ItemLocationIndex, MI.ItemSerial, MI.ItemID, MI.ItemRemainCount, MI.ItemDurability, MI.RandomSeed, MI.CoolTime, MI.ItemLevel, MI.ItemPotential, MI.SoulBoundFlag
				, MI.ItemOption, MI.SealCount, MI.ItemMaterializeDate, MI.EternityFlag, MI.ItemExpireDate, MI.AdditiveItemID
			FROM dbo.WorldDepots WD WITH (NOLOCK, INDEX(PK_WorldDepots), FORCESEEK)
				INNER JOIN dbo.MaterializedItems MI WITH (NOLOCK, INDEX (PK_MaterializedItems), FORCESEEK) ON WD.MaterializedItemID = MI.MaterializedItemID
			WHERE WD.AccountID = @intAccountID
				AND MI.ItemRemainCount > 0
				AND MI.ItemLocationCode = @inyItemLocationCode
			OPTION (KEEPFIXED PLAN, FORCE ORDER, LOOP JOIN);

		ELSE
			SELECT ItemLocationCode, ItemLocationIndex, ItemSerial, ItemID, ItemRemainCount, ItemDurability, RandomSeed, CoolTime, ItemLevel, ItemPotential, SoulBoundFlag
				, ItemOption, SealCount, ItemMaterializeDate, EternityFlag, ItemExpireDate, AdditiveItemID
			FROM dbo.MaterializedItems WITH (NOLOCK, INDEX (IX_NNI_MaterializedItems_OwnerCharacterID_ItemLocationCode), FORCESEEK)
			WHERE OwnerCharacterID = @inbCharacterID
				AND ItemLocationCode = @inyItemLocationCode
				AND (@inyItemLocationCode > 1 OR (@inyItemLocationCode = 1 AND ItemLocationIndex < 200))
				AND ItemRemainCount > 0
			OPTION (KEEPFIXED PLAN);
	END

	ELSE
		SELECT ItemLocationCode, ItemLocationIndex, ItemSerial, ItemID, ItemRemainCount, ItemDurability, RandomSeed, CoolTime, ItemLevel, ItemPotential, SoulBoundFlag
			, ItemOption, SealCount, ItemMaterializeDate, EternityFlag, ItemExpireDate, AdditiveItemID
		FROM dbo.MaterializedItems WITH (NOLOCK, INDEX (IX_NNI_MaterializedItems_OwnerCharacterID_ItemLocationCode), FORCESEEK)
		WHERE OwnerCharacterID = @inbCharacterID
			AND (ItemLocationCode <= 4 OR ItemLocationCode BETWEEN 7 AND 8 OR ItemLocationCode BETWEEN 19 AND 21)
			AND (ItemLocationCode > 1 OR (ItemLocationCode = 1 AND ItemLocationIndex < 200))
			AND ItemRemainCount > 0
		UNION ALL
		SELECT MI.ItemLocationCode, MI.ItemLocationIndex, MI.ItemSerial, MI.ItemID, MI.ItemRemainCount, MI.ItemDurability, MI.RandomSeed, MI.CoolTime, MI.ItemLevel, MI.ItemPotential, MI.SoulBoundFlag
			, MI.ItemOption, MI.SealCount, MI.ItemMaterializeDate, MI.EternityFlag, MI.ItemExpireDate, MI.AdditiveItemID
		FROM dbo.WorldDepots WD WITH (NOLOCK, INDEX(PK_WorldDepots), FORCESEEK)
			INNER JOIN dbo.MaterializedItems MI WITH (NOLOCK, INDEX (PK_MaterializedItems), FORCESEEK) ON WD.MaterializedItemID = MI.MaterializedItemID
		WHERE WD.AccountID = @intAccountID
			AND MI.ItemRemainCount > 0
			AND MI.ItemLocationCode BETWEEN 17 AND 18
		OPTION (KEEPFIXED PLAN, FORCE ORDER, LOOP JOIN);

	/**_# ??? ???? ??? 103151? ?????.*/
	IF @@ROWCOUNT = 0
	BEGIN
		SET @intReturnValue = 103151;
		GOTO ErrorHandler;
	END
END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	EXEC @intReturnValue = dbo.P_AddErrorLog;

RETURN @intReturnValue;
GO
