CREATE PROCEDURE [dbo].[P_GetListPVPLogForETL]
	  @dtmBasisDate datetime --// ?? ??
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int, @intLogTableSuffix int = dbo.FN_LogTableSuffix(@dtmBasisDate), @intWorldID int;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY
	SELECT TOP (1) @intWorldID = WorldID FROM dbo.WorldCoverage WITH (NOLOCK) ORDER BY WorldID;

	IF @intLogTableSuffix = 0
		SELECT A.PVPStartDate, A.PVPEndDate, B.PVPStartID, B.MaxPlayerCount, B.PVPModeCode, B.PVPModeDetailCode, B.BreakIntoFlag, B.ItemUseFlag, B.SecreteFlag, B.MapID, @intWorldID AS WorldID, RoomOpenCharacterID, CheifCharacterID
		FROM dbo.PVPStartIDs A WITH (NOLOCK)
			INNER JOIN dbo.PVPStartLogs0 B WITH (NOLOCK) ON A.PVPStartID = B.PVPStartID
		WHERE A.PVPStartDate >= CAST(@dtmBasisDate AS datetime2(0)) AND A.PVPStartDate < CAST(@dtmBasisDate + 1 AS datetime2(0))
		OPTION (MAXDOP 1);

	ELSE IF @intLogTableSuffix = 1
		SELECT A.PVPStartDate, A.PVPEndDate, B.PVPStartID, B.MaxPlayerCount, B.PVPModeCode, B.PVPModeDetailCode, B.BreakIntoFlag, B.ItemUseFlag, B.SecreteFlag, B.MapID, @intWorldID AS WorldID, RoomOpenCharacterID, CheifCharacterID
		FROM dbo.PVPStartIDs A WITH (NOLOCK)
			INNER JOIN dbo.PVPStartLogs1 B WITH (NOLOCK) ON A.PVPStartID = B.PVPStartID
		WHERE A.PVPStartDate >= CAST(@dtmBasisDate AS datetime2(0)) AND A.PVPStartDate < CAST(@dtmBasisDate + 1 AS datetime2(0))
		OPTION (MAXDOP 1);

	ELSE
		SELECT A.PVPStartDate, A.PVPEndDate, B.PVPStartID, B.MaxPlayerCount, B.PVPModeCode, B.PVPModeDetailCode, B.BreakIntoFlag, B.ItemUseFlag, B.SecreteFlag, B.MapID, @intWorldID AS WorldID, RoomOpenCharacterID, CheifCharacterID
		FROM dbo.PVPStartIDs A WITH (NOLOCK)
			INNER JOIN dbo.PVPStartLogs2 B WITH (NOLOCK) ON A.PVPStartID = B.PVPStartID
		WHERE A.PVPStartDate >= CAST(@dtmBasisDate AS datetime2(0)) AND A.PVPStartDate < CAST(@dtmBasisDate + 1 AS datetime2(0))
		OPTION (MAXDOP 1);

END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	EXEC @intReturnValue = dbo.P_AddErrorLog;

RETURN @intReturnValue;
GO
