CREATE PROCEDURE [dbo].[P_GetListPointLog]
	  @dtmBasisDate datetime --// ?? ??
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int, @dt2LogDate datetime2(0), @intLogTableSuffix int;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY

	SET @dt2LogDate = CONVERT(datetime2(0), CONVERT(date, @dtmBasisDate));
	SET @intLogTableSuffix = dbo.FN_LogTableSuffix(@dt2LogDate);

	IF @intLogTableSuffix = 0
		SELECT LogDate, CharacterID, PointCode, PointBefore, PointAfter, MapID, IP
		  FROM dbo.PointLogs0 WITH (NOLOCK)
		 WHERE LogDate >= @dt2LogDate AND LogDate < DATEADD(DAY, 1, @dt2LogDate);

	ELSE IF @intLogTableSuffix = 1
		SELECT LogDate, CharacterID, PointCode, PointBefore, PointAfter, MapID, IP
		  FROM dbo.PointLogs1 WITH (NOLOCK)
		 WHERE LogDate >= @dt2LogDate AND LogDate < DATEADD(DAY, 1, @dt2LogDate);

	ELSE
		SELECT LogDate, CharacterID, PointCode, PointBefore, PointAfter, MapID, IP
		  FROM dbo.PointLogs2 WITH (NOLOCK)
		 WHERE LogDate >= @dt2LogDate AND LogDate < DATEADD(DAY, 1, @dt2LogDate);

END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	EXEC @intReturnValue = dbo.P_AddErrorLog;

RETURN @intReturnValue;
GO
