	WHERE TradeStatusCode BETWEEN 1 AND 2 AND TradeDate >= CAST(@dtmBasisDate AS datetime2(0)) AND TradeDate < CAST(@dtmBasisDate + 1 AS datetime2(0))
	OPTION (MAXDOP 1);
