BEGIN TRY
	/**_# [WeeklyGuildContributionPoint] ???? SELECT ???.*/
	SELECT RANK() OVER(ORDER BY WG.WeeklyGuildContributionPoint DESC) AS Ranking, WG.CharacterID, CH.CharacterName, CS.JobCode, WG.WeeklyGuildContributionPoint
