CREATE PROCEDURE [dbo].[P_GetPVPTournamentResult]
	  @inbPVPTournamentID bigint --// PVP ???? ID
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY
	/**_# [PVPTournamentIDs] ???? INSERT???.*/
	SELECT A.PVPTournamentSeqence, A.CharacterID, B.CharacterName, A.FinalRound, A.ResultFlag
	FROM dbo.PVPTournamentResults A WITH(NOLOCK, INDEX(PK_PVPTournamentResults), FORCESEEK)
		INNER JOIN dbo.Characters B WITH(NOLOCK, INDEX(PK_Characters), FORCESEEK) ON A.CharacterID = B.CharacterID
	WHERE A.PVPTournamentID = @inbPVPTournamentID
	ORDER BY A.PVPTournamentSeqence
	OPTION (KEEPFIXED PLAN);

END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	EXEC @intReturnValue = dbo.P_AddErrorLog;

RETURN @intReturnValue;
