SET QUOTED_IDENTIFIER ON
GO
/**
version : 11
author : ???
e-mail : ohtack@eyedentitygames.com
created date : 2012-10-23
description : ???? ?? ??? ?????.
result set : 
	@inyRankCode = 1 : Ranking/int, JobCode/tinyint, CharacterID/bigint, CharacterName/nvarchar(50), GuildName/nvarchar(50), AcquireGoldKeyCount/int
	@inyRankCode = 2 : Ranking/int, JobCode/tinyint, CharacterID/bigint, CharacterName/nvarchar(50), GuildName/nvarchar(50), PlayTime/int
	@inyRankCode = 3 : Ranking/int, GuildID/int, GuildName/nvarchar(50), GuildMark/smallint, GuildMarkBG/smallint, GuildMarkBorder/smallint, AcquireGoldKeyCount/int
return value :
0 = ??? ????.
1 = ????? Commit? ? ?? ?????. ????? Rollback???.
100 = ??? ??? ???????. dbo.ErrorLogs ???? ?????.
history :
10 = ??? ?? ???? ?? ?? by ??? at 2013-04-17
**/

CREATE PROCEDURE [dbo].[P_GetPageAlteiaRanking]
	  @insRankerCount smallint --// ??? ? ?? ? (1 ~ 255)
	, @inyRankCode tinyint --// 1=????, 2=?????, 3=??
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END
BEGIN TRY
	IF @inyRankCode = 1
	BEGIN
		WITH RANKING AS(
			SELECT ROW_NUMBER() OVER(ORDER BY AcquireGoldKeyCount DESC, GoldKeyRegisterDate) AS Ranking, CharacterID, AcquireGoldKeyCount
			FROM dbo.PlayAlteia A WITH(NOLOCK, INDEX(IX_NN_PlayAlteia_AcquireGoldKeyCount_GoldKeyRegisterDate))	
		)
		SELECT A.Ranking, CS.JobCode, A.CharacterID, C.CharacterName, ISNULL(G.GuildName, N'') AS GuildName, A.AcquireGoldKeyCount
		FROM RANKING A
			INNER JOIN dbo.Characters C WITH(NOLOCK, INDEX(PK_Characters), FORCESEEK) ON A.CharacterID = C.CharacterID
			INNER JOIN dbo.CharacterStatus CS WITH(NOLOCK, INDEX(PK_CharacterStatus), FORCESEEK) ON A.CharacterID = CS.CharacterID
			LEFT OUTER JOIN dbo.GuildMembers GM WITH(NOLOCK, INDEX(IX_UN_GuildMembers_CharacterID), FORCESEEK) ON A.CharacterID = GM.CharacterID
			LEFT OUTER JOIN dbo.Guilds G WITH(NOLOCK, INDEX(PK_Guilds), FORCESEEK) ON GM.GuildID = G.GuildID
		WHERE A.Ranking <= @insRankerCount
		OPTION(KEEPFIXED PLAN);
	END
	ELSE IF @inyRankCode = 2
	BEGIN
		WITH RANKING AS(
			SELECT TOP (@insRankerCount) ROW_NUMBER() OVER(ORDER BY PlayTime, PlayTimeRegisterDate) AS Ranking, CharacterID, PlayTime
			FROM dbo.PlayAlteia WITH(NOLOCK, INDEX(IX_NN_PlayAlteia_PlayTime_PlayTimeRegisterDate))	
		)
		SELECT A.Ranking, CS.JobCode, A.CharacterID, C.CharacterName, ISNULL(G.GuildName, N'') AS GuildName, A.PlayTime
		FROM RANKING A
			INNER JOIN dbo.Characters C WITH(NOLOCK, INDEX(PK_Characters), FORCESEEK) ON A.CharacterID = C.CharacterID
			INNER JOIN dbo.CharacterStatus CS WITH(NOLOCK, INDEX(PK_CharacterStatus), FORCESEEK) ON A.CharacterID = CS.CharacterID
			LEFT OUTER JOIN dbo.GuildMembers GM WITH(NOLOCK, INDEX(IX_UN_GuildMembers_CharacterID), FORCESEEK) ON A.CharacterID = GM.CharacterID
			LEFT OUTER JOIN dbo.Guilds G WITH(NOLOCK, INDEX(PK_Guilds), FORCESEEK) ON GM.GuildID = G.GuildID
		WHERE A.Ranking <= @insRankerCount
		OPTION(KEEPFIXED PLAN);
	END
	ELSE IF @inyRankCode = 3
	BEGIN
		WITH RANKING AS(
			SELECT TOP (@insRankerCount) ROW_NUMBER() OVER(ORDER BY AcquireGoldKeyCount DESC, UpdateDate) AS Ranking, GuildID, AcquireGoldKeyCount
			FROM dbo.AlteiaGuildRank WITH(NOLOCK, INDEX(IX_NN_AlteiaGuildRank_AcquireGoldKeyCount_UpdateDate))
		)
		SELECT A.Ranking, A.GuildID, B.GuildName, B.GuildMark, B.GuildMarkBG, B.GuildMarkBorder, A.AcquireGoldKeyCount
		FROM RANKING A
			INNER JOIN dbo.Guilds B WITH(NOLOCK, INDEX(PK_Guilds), FORCESEEK) ON A.GuildID = B.GuildID
		WHERE A.Ranking <= @insRankerCount
		OPTION(KEEPFIXED PLAN);

	END
END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	EXEC @intReturnValue = dbo.P_AddErrorLog;
RETURN @intReturnValue;
GO
