CREATE PROCEDURE [dbo].[P_GetPageBorad]
	 @intFirstSeq int --// ??? ?? ???? ??? ??? (?? ????? 1)
	,@intLastSeq int --// ??? ?? ???? ??? ???, -.??? ????? ??? ??? ?? ???? ??? ???, -.?? ????? 1, -.?? ??? ?? ????? ?? ???? ??? ???
	,@intDispType tinyint --// 0:????/?? ??? ?? ???, 1:?? ??? ???, 2:?? ??? ???
	,@intPage int --// ??? ???? ?? ??? (?? ????? 1)
	,@nvcUserID nvarchar(50) = null --// ??? ?? ??? (@nvcUserID ?? null ? ?? ???? ??? ?? ???. UserID ?? ??? ?? ??? ??? ?? ???.)
WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int
DECLARE	@TotalCount smallint --// ???
/**_# ??? ?? ?? */
DECLARE @member table 
(
	idx	smallint identity(1,1)
,	m_serial int not null
)

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY

/**_# ??? ????? ??? ??? ?? */


IF @nvcUserID IS NULL
BEGIN
	IF @intDispType =  0
	BEGIN
		/**_## ?? ?? OR ?? ??? ?? ??? (SELECT ?).*/
		INSERT INTO @member (m_serial)
		SELECT BoardSeq FROM (SELECT TOP 200 BoardSeq FROM dbo.BoardMain WHERE BoardSeq >= @intLastSeq AND DeleteFlag = 0 ORDER BY BoardSeq DESC) a
	END
	ELSE IF @intDispType =  1
	BEGIN
		/**_## ??? ?? ?? ???(SELECT ?).*/
		INSERT INTO @member (m_serial)	
		SELECT BoardSeq FROM (SELECT TOP 200 BoardSeq FROM dbo.BoardMain WHERE BoardSeq >= @intFirstSeq AND DeleteFlag = 0 ORDER BY BoardSeq DESC) a
	END
	ELSE IF @intDispType =  2
	BEGIN
		/**_## ?? ??? ?? ???(SELECT ?).*/	
		INSERT INTO @member (m_serial)	
		SELECT BoardSeq FROM (SELECT TOP 200 BoardSeq FROM dbo.BoardMain WHERE BoardSeq <= @intFirstSeq AND DeleteFlag = 0 ORDER BY BoardSeq DESC) a
	END
END
ELSE
BEGIN
	IF @intDispType =  0
	BEGIN
		/**_## ?? ?? OR ?? ??? ?? ??? (SELECT ?).*/
		INSERT INTO @member (m_serial)
		SELECT BoardSeq FROM (SELECT TOP 200 BoardSeq FROM dbo.BoardMain WHERE BoardSeq >= @intLastSeq AND UserID = @nvcUserID AND DeleteFlag = 0 ORDER BY BoardSeq DESC) a
	END
	ELSE IF @intDispType =  1
	BEGIN
		/**_## ??? ?? ?? ???(SELECT ?).*/
		INSERT INTO @member (m_serial)	
		SELECT BoardSeq FROM (SELECT TOP 200 BoardSeq FROM dbo.BoardMain WHERE BoardSeq >= @intFirstSeq AND UserID = @nvcUserID AND DeleteFlag = 0 ORDER BY BoardSeq DESC) a
	END
	ELSE IF @intDispType =  2
	BEGIN
		/**_## ?? ??? ?? ???(SELECT ?).*/	
		INSERT INTO @member (m_serial)	
		SELECT BoardSeq FROM (SELECT TOP 200 BoardSeq FROM dbo.BoardMain WHERE BoardSeq <= @intFirstSeq AND UserID = @nvcUserID AND DeleteFlag = 0 ORDER BY BoardSeq DESC) a
	END
END

/**_# ? ? ?? ?? */
	SET @TotalCount = @@ROWCOUNT

/**_# ??? ???? ?? ???? ??? 102114 ?(?) ?????.*/
	IF @TotalCount = 0
	BEGIN
		SET @intReturnValue = 102114;
		GOTO ErrorHandler;
	END
		
/**_# ??? ??? ?? ???? ??? ???? ??? */
	SELECT
		 @intFirstSeq=MIN(CASE WHEN idx = 1 THEN m_serial END)
		,@intLastSeq= MIN(CASE WHEN idx = @TotalCount THEN m_serial END)
	FROM
		@member

/**_# ?? ???? ??? ????  */
	SELECT
		BoardSeq, UserIndex, UserID, [Subject], Contents, WriteDate, CommentCount, AttachedFlag, @intFirstSeq AS FirstSerial
		, @intLastSeq AS LastSerial, @TotalCount AS TotalCount
	FROM
		@member m
	INNER JOIN
		dbo.BoardMain c
	ON
		m.m_serial = c.BoardSeq
	WHERE
		m.idx >= 20 * ((@intPage-1) % 10) + 1 AND m.idx <= 20 * ((@intPage-1) % 10 +1)
	ORDER BY c.BoardSeq DESC
	
END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	SET @intReturnValue = 100;

RETURN @intReturnValue;
GO
