			INNER JOIN dbo.Characters C WITH(NOLOCK, INDEX(PK_Characters), FORCESEEK) ON C.CharacterID = PJ.CharacterID
		WHERE  PartyID = @inbPartyID
		OPTION (FORCE ORDER, LOOP JOIN, KEEPFIXED PLAN);

	
END TRY
