			SELECT @dt2Now, FarmID, FieldIndex, CharacterID, @xmlAttachments, 1 FROM @tblFieldDeleteLogs OPTION (KEEPFIXED PLAN);
		END
	END
	ELSE
	BEGIN
		INSERT dbo.FieldDeleteLogs2 (LogDate, FarmID, FieldIndex, CharacterID, ItemID, PlantDate, ElapsedTime, HarvestFlag)
		SELECT @dt2Now, FarmID, FieldIndex, CharacterID, ItemID, PlantDate, ElapsedTime, 1 FROM @tblFieldDeleteLogs OPTION (KEEPFIXED PLAN);

		IF @xmlAttachments IS NOT NULL
		BEGIN
			INSERT dbo.FieldAttachmentDeleteLogs2 (LogDate, FarmID, FieldIndex, CharacterID, Attachments, HarvestFlag)
			SELECT @dt2Now, FarmID, FieldIndex, CharacterID, @xmlAttachments, 1 FROM @tblFieldDeleteLogs OPTION (KEEPFIXED PLAN);
		END
	END

END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	EXEC @intReturnValue = dbo.P_AddErrorLog;

RETURN @intReturnValue;
