    , @bitInputType tinyint = 0 --// ??? ???? (0=????, 1=?????)
    , @inyInputTeamColorCode tinyint = NULL --// 1=??,2=?? (????? ? Color) (????(@bitInputType=0)? ???? ?? ??)
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
