CREATE PROCEDURE [dbo].[P_ModSkillLevel]
	  @inbCharacterID bigint --// ??? ID
	, @intSkillID int --// ?? ID
	, @inySkillLevel tinyint --// ?? ? ?? ??
	, @intCoolTime int --// ? ?? (?)
	, @insChangedSkillPoint smallint --// ??? ????? ??? ?? ???. ?? : ?????? -, ?????? + ??? ?????.
	, @inySkillChangeCode tinyint --// 2=?? ?? ??, 13=?? ?? ?? (by ???)
