	, @inySkillCode tinyint = 1 --// 1=1? ??, 2=2? ??
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int
	, @dt2Now datetime2(0) = GETDATE()
	, @inySkillLevelBefore tinyint;

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY
	BEGIN TRANSACTION;

	/**_# [CharacterStatus]???? UPDATE???.*/
	/**_# ?? ???? ???? 103145? ?????.*/
	UPDATE dbo.CharacterStatus
	SET SkillPoint += CASE @inySkillCode WHEN 1 THEN @insChangedSkillPoint ELSE 0 END
		, SkillPoint2 += CASE @inySkillCode WHEN 2 THEN @insChangedSkillPoint ELSE 0 END
	WHERE CharacterID = @inbCharacterID;

	/**_# ???? ??? 103102? ?????.*/
	IF @@ROWCOUNT = 0
	BEGIN
		SET @intReturnValue = 103102;
		GOTO ErrorHandler;
	END

	/**_# [Skills]???? UPDATE???.*/
	UPDATE dbo.Skills
	SET @inySkillLevelBefore = SkillLevel
		, SkillLevel = @inySkillLevel
		, CoolTime = @intCoolTime
		, UsedSkillPoint -= @insChangedSkillPoint
	WHERE CharacterID = @inbCharacterID AND SkillID = @intSkillID AND SkillCode = @inySkillCode;

	/**_# ??? ??? ??? 103144? ?????.*/
	IF @@ROWCOUNT = 0
	BEGIN
		SET @intReturnValue = 103144;
		GOTO ErrorHandler;
	END

	/**_# SkillLevel? ?? ?/? ?? ????, ROLLBACK ? 0? ???? ?? ?????.*/
	IF @inySkillLevelBefore = @inySkillLevel
	BEGIN
		ROLLBACK TRANSACTION;
		RETURN 0;
	END

	COMMIT TRANSACTION;

	/**_# [P_AddSkillLog]? ???? ??? ?????.*/
	EXEC @intReturnValue = dbo.P_AddSkillLog
		  @dt2LogDate = @dt2Now
		, @inbCharacterID = @inbCharacterID
		, @inySkillChangeCode = @inySkillChangeCode
		, @intSkillID = @intSkillID
		, @inySkillLevelBefore = @inySkillLevelBefore
		, @inySkillLevelAfter = @inySkillLevel
		, @intChannelID = @intChannelID
		, @intMapID = @intMapID;

END TRY
BEGIN CATCH
	IF ERROR_NUMBER() = 547 AND ERROR_MESSAGE() LIKE N'%CK_CharacterStatus_SkillPoint%'
		SET @intReturnValue = 103145;

