		FROM @tblDarkLairRankingID A
			INNER JOIN dbo.DarkLairRanking B ON A.DarkLairRankingID = B.DarkLairRankingID
		WHERE Seq BETWEEN @i AND @i + 99;

		SET @i += 100;

