	INSERT dbo.Mails (SenderCharacterID, ReceiverCharacterID, MailTypeCode, DeliveryTypeCode, Subject, Content, SendDate, ReadFlag, DeleteFlag, AttachCoin, AttachCoinReceiveFlag, SenderName, SystemMailFKey, NewFlag, MailTabCode)
	VALUES (@inbMaxLevelCharacterID, @inbReceiverCharacterID, 19, CASE @intAttachItemCount WHEN 1 THEN 1 ELSE 2 END, @nvcSubject, @nvcContent, @dt2Now, 0, 0, @inbAttachCoin, 0, @nvcSenderName, @inbSystemMailFKey, @bitNewFlag, @inyMailTabCode);
	SET @intMailID = SCOPE_IDENTITY();
	IF @intAttachItemCount > 0
	BEGIN
