CREATE PROCEDURE [dbo].[P_SwitchItemLocation2]
	  @inbCharacterID bigint --// ??? ID
	, @inyItemLocationCodeA tinyint --// ??? ???? ?? 1=????, 2=????, 3=??, 4=??? ????, 5=?? ????, 7=?? ????, 8=??, 9=??, 10=?, 19=????
	, @inyItemLocationIndexA tinyint --// ??? ???? ?? ??? ?
	, @inbItemSerialA bigint --// ??? ???? ??? ???
	, @inyItemLocationCodeB tinyint --// ??? ???? ?? 1=????, 2=????, 3=??, 4=??? ????, 5=?? ????, 7=?? ????, 8=??, 9=??, 10=?, 19=????
	, @inyItemLocationIndexB tinyint --// ??? ???? ?? ??? ?
	, @inbItemSerialB bigint --// ??? ???? ??? ???
--WITH EXECUTE AS 'SPExecutor'
AS
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @intReturnValue int;
DECLARE @tblSRC table (
	ItemLocationCode tinyint NOT NULL,
	MaterializedItemID bigint NULL
);

/**_# Rollback and return if inside an uncommittable transaction.*/
IF XACT_STATE() = -1
BEGIN
	SET @intReturnValue = 1;
	GOTO ErrorHandler;
END

BEGIN TRY
	IF @inbItemSerialA = @inbItemSerialB
	BEGIN
		SET @intReturnValue = 103183;
		GOTO ErrorHandler;
	END

	IF @inyItemLocationCodeA = @inyItemLocationCodeB AND @inyItemLocationCodeA NOT IN (1, 7, 19)
	BEGIN
		SET @intReturnValue = 103310;
		GOTO ErrorHandler;
	END

	BEGIN TRANSACTION;

	WITH C (ItemSerial, OwnerCharacterID, ItemLocationCode, ItemLocationIndex) AS (
		SELECT @inbItemSerialA, @inbCharacterID, @inyItemLocationCodeB, @inyItemLocationIndexB
		UNION ALL
		SELECT @inbItemSerialB, @inbCharacterID, @inyItemLocationCodeA, @inyItemLocationIndexA
	)
	UPDATE dbo.MaterializedItems
	SET ItemLocationCode = C.ItemLocationCode
		, ItemLocationIndex = C.ItemLocationIndex
	FROM C
		INNER JOIN dbo.MaterializedItems MI ON C.ItemSerial = MI.ItemSerial AND C.OwnerCharacterID = MI.OwnerCharacterID;

	IF @@ROWCOUNT <> 2
	BEGIN
		SET @intReturnValue = 103178;
		GOTO ErrorHandler;
	END

	COMMIT TRANSACTION;
END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
IF XACT_STATE() <> 0
	ROLLBACK TRANSACTION;

IF @intReturnValue IS NULL OR @intReturnValue = 0
	EXEC @intReturnValue = dbo.P_AddErrorLog;

RETURN @intReturnValue;
GO
