		VALUES (@dt2Now, @inbCharacterID, @inyPointCode, @inbRemainPoint + @inbPoint, @inbRemainPoint, @intMapID, dbo.FN_IP2IPNumber(@vchIP));

	ELSE
		INSERT dbo.PointLogs2 (LogDate, CharacterID, PointCode, PointBefore, PointAfter, MapID, IP)
		VALUES (@dt2Now, @inbCharacterID, @inyPointCode, @inbRemainPoint + @inbPoint, @inbRemainPoint, @intMapID, dbo.FN_IP2IPNumber(@vchIP));

END TRY
BEGIN CATCH
	GOTO ErrorHandler;
END CATCH;

RETURN 0;

ErrorHandler:
